#include <bits/stdc++.h>
using namespace std;

typedef long long LL;
const LL MOD = 1000000007LL;
const int N = 302;

int n;
int c[N][N];
char s[N];

LL dp[202][202][202];

LL dfs(int pre, int x, int y) {
    if (dp[pre][x][y] != -1) return dp[pre][x][y];
    if (x == 0 && y == 0) return 1;

    dp[pre][x][y] = 0;

    if (pre > 0 && y > 0)
        dp[pre][x][y] += dfs(pre - 1, x, y - 1);

    if (x > 0)
        dp[pre][x][y] += dfs(pre + 1, x - 1, y);

    dp[pre][x][y] %= MOD;
    return dp[pre][x][y];
}

int main() {
    for (int i = 0; i < N; i++)
        c[i][0] = 1;

    for (int i = 1; i < N; i++)
        for (int j = 1; j <= i; j++)
            c[i][j] = (c[i - 1][j] + c[i - 1][j - 1]) % MOD;

    memset(dp, -1, sizeof(dp));
    scanf("%d %s", &n, s + 1);

    int len = strlen(s + 1);
    int cnt = 0, mxR = 0;

    for (int i = 1; i <= len; i++) {
        if (s[i] == '(')
            cnt++;
        else
            cnt--;

        if (cnt < 0)
            mxR = max(mxR, -cnt);
    }

    LL ans = 0;

    for (int x = 0; x < N; x++) {
        for (int y = 0; y < N; y++) {
            if (x - y < mxR) continue;

            int rem = 2 * n - len - x - y;
            if (rem < 0) continue;

            int value = rem + x - y + cnt;
            if (value % 2 != 0) continue;

            int R = value / 2;
            int L = rem - R;

            if (L < 0 || R < 0) continue;

            ans = (ans + dfs(0, x, y) * dfs(x - y + cnt, L, R)) % MOD;
        }
    }

    cout << ans << '\n';
    return 0;
}

